201	        if (currentOwner == null) {
202	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
203	        }
204	        currentOwner.setAddress(ownerFieldsDto.getAddress());
205	        currentOwner.setCity(ownerFieldsDto.getCity());
206	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
207	        currentOwner.setLastName(ownerFieldsDto.getLastName());
208	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
209	        this.clinicService.saveOwner(currentOwner);
210	        OwnerDto ownerDto = ownerMapper.toOwnerDto(currentOwner);
211	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
212	        return new ResponseEntity<>(ownerDto, HttpStatus.NO_CONTENT);
