292	    private static boolean isBlank(String value) {
293	        return value == null || value.isBlank();
294	    }
295	
296	    /**
297	     * The set of disposable email domains that owners may not register with. Compared
298	     * case-insensitively against the domain part of the supplied email.
299	     */
300	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
301	        "mailinator.com", "tempmail.com", "guerrillamail.com");
302	
303	    /**
304	     * Rejects an owner whose email domain is on the disposable-domain blocklist
305	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is optional:
306	     * a {@code null} or blank value, or one without an {@code '@'} domain part, is accepted here (the
307	     * {@code @Email} Bean Validation constraint governs format). The domain is compared
308	     * case-insensitively; the stored email is already lower-cased.
309	     *
310	     * @param email the owner's email (may be {@code null})
311	     * @throws DisposableEmailDomainException if the email's domain is on the blocklist
312	     */
313	    private static void validateEmailDomain(String email) {
314	        if (isBlank(email)) {
315	            return;
316	        }
317	        int at = email.lastIndexOf('@');
318	        if (at < 0) {
319	            return;
320	        }
321	        String domain = email.substring(at + 1).trim().toLowerCase(java.util.Locale.ROOT);
322	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
323	            throw new DisposableEmailDomainException(email);
324	        }
325	    }
326	
327	    /**
328	     * The fixed, region-keyed inclusive 4-digit postcode ranges. A region absent from this table
329	     * (locality {@code UNKNOWN}) imposes no range, so any 4-digit postcode is accepted there.
330	     */
331	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
332	        "NSW", new int[] {2000, 2099},
333	        "VIC", new int[] {3000, 3099},
334	        "QLD", new int[] {4000, 4099});
335	
336	    /**
337	     * Validates a supplied {@code postcode} against the owner's city region. Postcode is optional:
338	     * a {@code null} or blank value is accepted (validation only applies WHEN PRESENT). When
339	     * present, the value has already passed the 4-digit format check (Bean Validation on the
340	     * request body); this enforces that it falls within the inclusive range for the city's region
341	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region imposes no range.
342	     *
343	     * @param postcode the supplied postcode (may be {@code null})
344	     * @param region the owner's locality/region derived from its city
345	     * @throws InvalidPostcodeException if the postcode is out of range for the region
346	     */
347	    private static void validatePostcode(String postcode, String region) {
348	        if (isBlank(postcode)) {
349	            return;
350	        }
351	        int[] range = REGION_POSTCODES.get(region);
352	        if (range == null) {
353	            return;
354	        }
355	        int value;
356	        try {
357	            value = Integer.parseInt(postcode);
358	        }
359	        catch (NumberFormatException e) {
360	            throw new InvalidPostcodeException(postcode);
361	        }
362	        if (value < range[0] || value > range[1]) {
363	            throw new InvalidPostcodeException(postcode);
364	        }
365	    }
366	
367	    /**
368	     * Normalizes a street address into the canonical form stored on and returned for a newly
369	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
370	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
371	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
372	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
373	     * value is what gets persisted, echoed back, and used for every address comparison (household
374	     * duplicate detection and the shared household identifier).
375	     *
376	     * @param rawAddress the address value as supplied by the client
377	     * @return the normalized address (possibly empty, never {@code null})
378	     */
379	    private static String normalizeAddress(String rawAddress) {
380	        if (rawAddress == null) {
381	            return "";
382	        }
383	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
384	        if (collapsed.isEmpty()) {
385	            return "";
386	        }
387	        String[] tokens = collapsed.split(" ");
388	        StringBuilder sb = new StringBuilder(collapsed.length());
389	        for (int i = 0; i < tokens.length; i++) {
390	            String token = tokens[i];
391	            switch (token) {
392	                case "ST" -> token = "STREET";
393	                case "RD" -> token = "ROAD";
394	                case "AVE" -> token = "AVENUE";
395	                default -> { }
396	            }
397	            if (i > 0) {
398	                sb.append(' ');
399	            }
400	            sb.append(token);
401	        }
402	        return sb.toString();
403	    }
404	
405	    /**
406	     * Builds the customer code assigned to a newly created owner. The code is formatted
407	     * {@code <REGION>-<HASH8>} where {@code REGION} is the region derived from the owner's postcode
408	     * (see {@link Owner#getRegion()}) and {@code HASH8} is the first 8 upper-case hex characters of
409	     * the SHA-256 digest of the owner's normalized (E.164) telephone concatenated with its last
410	     * name (e.g. {@code NSW-1A2B3C4D}). No sequence number is involved, so the code depends only on
411	     * the owner's own region and identity.
412	     *
413	     * @param owner the owner being created, with telephone already normalized and postcode/city set
414	     * @return the customer code to assign
415	     */
416	    private static String customerCodeFor(Owner owner) {
417	        return owner.getRegion() + "-" + telephoneNameHash(owner.getTelephone(), owner.getLastName());
418	    }
419	
420	    /**
421	     * De-duplicates a freshly computed customer code against the codes already assigned to existing
422	     * owners. When no existing owner carries the given code it is returned unchanged; otherwise the
423	     * smallest suffix {@code -<n>} with {@code n >= 2} that yields a code no existing owner holds is
424	     * appended, guaranteeing distinct owners always receive distinct customer codes.
425	     *
426	     * @param customerCode the customer code computed for the owner being created
427	     * @return the de-duplicated customer code, unique among existing owners
428	     */
429	    private String deduplicateCustomerCode(String customerCode) {
430	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
431	            .map(Owner::getCustomerCode)
432	            .filter(java.util.Objects::nonNull)
433	            .collect(java.util.stream.Collectors.toSet());
434	        if (!existing.contains(customerCode)) {
435	            return customerCode;
436	        }
437	        int n = 2;
438	        while (existing.contains(customerCode + "-" + n)) {
439	            n++;
440	        }
441	        return customerCode + "-" + n;
442	    }
443	
444	    /**
445	     * Computes the {@code HASH8} segment of the customer code: the first 8 upper-case hex
446	     * characters of the SHA-256 digest of the normalized (E.164) telephone concatenated with the
447	     * last name.
448	     *
449	     * @param normalizedTelephone the owner's telephone in E.164 form
450	     * @param lastName the owner's last name
451	     * @return the 8-character upper-case hex hash
452	     */
453	    private static String telephoneNameHash(String normalizedTelephone, String lastName) {
454	        String key = (normalizedTelephone == null ? "" : normalizedTelephone)
455	            + (lastName == null ? "" : lastName);
456	        try {
457	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
458	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
459	            StringBuilder sb = new StringBuilder(digest.length * 2);
460	            for (byte b : digest) {
461	                sb.append(String.format("%02x", b));
462	            }
463	            return sb.substring(0, 8).toUpperCase(java.util.Locale.ROOT);
464	        }
465	        catch (java.security.NoSuchAlgorithmException e) {
466	            throw new IllegalStateException("SHA-256 not available", e);
467	        }
468	    }
469	
470	    /**
471	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
472	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
473	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
474	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits, and the length of
475	     * the national number must match the country code: {@code +61} requires 9 national digits and
476	     * {@code +1} requires 10.
477	     *
478	     * @param rawTelephone the telephone value as supplied by the client
479	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
480	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
481	     */
482	    private static String normalizeTelephone(String rawTelephone) {
483	        if (rawTelephone == null) {
484	            throw new InvalidTelephoneException(rawTelephone);
485	        }
486	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
487	        String e164;
488	        if (cleaned.startsWith("+")) {
489	            String digits = cleaned.substring(1);
490	            if (!digits.matches("[0-9]+")) {
491	                throw new InvalidTelephoneException(rawTelephone);
492	            }
493	            e164 = "+" + digits;
494	        } else {
495	            if (!cleaned.matches("[0-9]+")) {
496	                throw new InvalidTelephoneException(rawTelephone);
497	            }
498	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
499	            e164 = "+61" + national;
500	        }
501	        int digitCount = e164.length() - 1;
502	        if (digitCount < 8 || digitCount > 15) {
503	            throw new InvalidTelephoneException(rawTelephone);
504	        }
505	        if (e164.startsWith("+61")) {
506	            if (e164.length() - "+61".length() != 9) {
507	                throw new InvalidTelephoneException(rawTelephone);
508	            }
509	        }
510	        else if (e164.startsWith("+1")) {
511	            if (e164.length() - "+1".length() != 10) {
512	                throw new InvalidTelephoneException(rawTelephone);
513	            }
514	        }
515	        return e164;
516	    }
517	
518	    /**
519	     * Determines whether any existing owner already carries the given identity key. The identity key
520	     * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) is the single value
521	     * all duplicate detection is based on, so two owners collide only when their whole identity keys
522	     * are equal.
523	     *
524	     * @param identityKey the identity key of the owner being created
525	     * @return {@code true} if another owner already has the same identity key
526	     */
527	    private boolean isIdentityKeyInUse(String identityKey) {
528	        return this.clinicService.findAllOwners().stream()
529	            .map(Owner::getIdentityKey)
530	            .anyMatch(identityKey::equals);
531	    }
532	
533	    /**
534	     * Finds an existing owner that the owner being created is a possible (soft) duplicate of: one
535	     * that shares the same last name (compared case-insensitively, whitespace-collapsed) and the
536	     * same postcode but carries a <em>different</em> telephone. Such a create is not rejected as a
537	     * hard duplicate, but is flagged. An owner with no postcode can never be a soft duplicate. When
538	     * several owners match, the earliest (lowest id) is returned so the result is deterministic.
539	     *
540	     * @param owner the owner being created (telephone already normalized, postcode set)
541	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
542	     */
543	    private Integer possibleDuplicateOf(Owner owner) {
544	        if (isBlank(owner.getPostcode())) {
545	            return null;
546	        }
547	        String normalizedLastName = normalizeIdentity(owner.getLastName());
548	        return this.clinicService.findAllOwners().stream()
549	            .filter(existing -> existing.getId() != null
550	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
551	                && owner.getPostcode().equals(existing.getPostcode())
552	                && !java.util.Objects.equals(owner.getTelephone(), existing.getTelephone()))
553	            .map(Owner::getId)
554	            .min(Integer::compareTo)
555	            .orElse(null);
556	    }
557	
558	    /**
559	     * Counts how many existing owners already share the given first name and last name with the
560	     * owner being created. Both names are compared case-insensitively (after trimming and
561	     * collapsing runs of whitespace). The count reflects the state before the new owner is
562	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
563	     *
564	     * @param firstName the first name of the owner being created
565	     * @param lastName the last name of the owner being created
566	     * @return the number of existing owners sharing the same first and last name
567	     */
568	    private int namesakeCount(String firstName, String lastName) {
569	        String normalizedFirstName = normalizeIdentity(firstName);
570	        String normalizedLastName = normalizeIdentity(lastName);
571	        return (int) this.clinicService.findAllOwners().stream()
572	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
573	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
574	            .count();
575	    }
576	
577	    /**
578	     * Counts how many members the owner being created belongs to in its household, including
579	     * itself, as of this create. Members are the owners sharing the given {@code householdId};
580	     * the new owner is not yet persisted, so its own membership is added to the existing count.
581	     * An owner not assigned to a shared household ({@code householdId} is {@code null}) is a
582	     * household of one.
583	     *
584	     * @param householdId the shared household identifier assigned to the owner being created, or
585	     *                    {@code null} if the owner does not share a household
586	     * @return the number of household members after this create (at least 1)
587	     */
588	    private int householdSizeAfterCreate(String householdId) {
589	        if (householdId == null) {
590	            return 1;
591	        }
592	        long existing = this.clinicService.findAllOwners().stream()
593	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
594	            .count();
595	        return (int) existing + 1;
596	    }
597	
598	    /**
599	     * The maximum number of owners permitted in a single city. Once a city already contains this
600	     * many owners it is considered full and no further owners may be created there.
601	     */
602	    private static final int CITY_CAPACITY = 50;
603	
604	    /**
605	     * Determines whether the given city has already reached its capacity, i.e. already contains
606	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
607	     * collapsing runs of whitespace to a single space and trimming.
608	     *
609	     * @param city the city of the owner being created
610	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
611	     */
612	    private boolean isCityAtCapacity(String city) {
613	        String normalizedCity = normalizeIdentity(city);
614	        long count = this.clinicService.findAllOwners().stream()
615	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
616	            .count();
617	        return count >= CITY_CAPACITY;
618	    }
619	
620	    /**
621	     * The maximum number of owners that may be created on any single day. Once this many owners
622	     * already carry a {@code registrationDate} of the current day, no further owners may be created
623	     * that day.
624	     */
625	    private static final int DAILY_REGISTRATION_LIMIT = 100;
626	
627	    /**
628	     * Determines whether the daily registration limit has already been reached, i.e. whether
629	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
630	     * their {@code registrationDate}.
631	     *
632	     * @param date the current day
633	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
634	     *         registered on the given date
635	     */
636	    /**
637	     * Rolls a registration date forward onto a business day. A date that already falls on a
638	     * weekday is returned unchanged; a Saturday or Sunday is rolled forward to the following
639	     * Monday. This adjusted date is what gets stored as the {@code registrationDate} and drives
640	     * everything derived from it (the membership number's year segment, the daily create-limit).
641	     *
642	     * @param date the effective registration date (supplied by the client or defaulted to the
643	     *             server's current date)
644	     * @return the same date if it is a weekday, otherwise the following Monday
645	     */
646	    private static LocalDate toBusinessDay(LocalDate date) {
647	        DayOfWeek dayOfWeek = date.getDayOfWeek();
648	        if (dayOfWeek == DayOfWeek.SATURDAY) {
649	            return date.plusDays(2);
650	        }
651	        if (dayOfWeek == DayOfWeek.SUNDAY) {
652	            return date.plusDays(1);
653	        }
654	        return date;
655	    }
656	
657	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
658	        long count = this.clinicService.findAllOwners().stream()
659	            .filter(existing -> date.equals(existing.getRegistrationDate()))
660	            .count();
661	        return count >= DAILY_REGISTRATION_LIMIT;
662	    }
663	
664	    /**
665	     * The number of owners that may be created on a single day before the bulk-signup warning is
666	     * raised. Once <em>more than</em> this many owners already carry the current business day as
667	     * their {@code registrationDate}, responses flag {@code bulkSignupWarning} true.
668	     */
669	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
670	
671	    /**
672	     * Determines whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
673	     * created today, i.e. already carry the current business day as their {@code registrationDate}.
674	     * This shares the daily create-limit's accumulation path (owners counted by registration date).
675	     *
676	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners are already
677	     *         registered on today's business day
678	     */
679	    private boolean isBulkSignupWarning() {
680	        LocalDate today = toBusinessDay(LocalDate.now());
681	        long count = this.clinicService.findAllOwners().stream()
682	            .filter(existing -> today.equals(existing.getRegistrationDate()))
683	            .count();
684	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
685	    }
686	
687	    /**
688	     * Determines whether the owner being created joins an existing household, i.e. some other owner
689	     * already carries the same computed {@code householdId} (equivalently, shares its normalized last
690	     * name and postcode). An owner with no postcode is never treated as joining a household, mirroring
691	     * the soft-duplicate rule that an owner with no postcode can never match one.
692	     *
693	     * @param owner the owner being created, with {@code householdId} already computed
694	     * @return {@code true} if another owner already belongs to the same household
695	     */
696	    private boolean isHouseholdInUse(Owner owner) {
697	        if (isBlank(owner.getPostcode())) {
698	            return false;
699	        }
700	        String householdId = owner.getHouseholdId();
701	        return this.clinicService.findAllOwners().stream()
702	            .anyMatch(existing -> existing.getId() != null
703	                && householdId.equals(existing.getHouseholdId()));
704	    }
705	
706	    /**
707	     * Derives the stable household identifier for a given last name and postcode. The value is the
708	     * first 12 upper-case hex characters of the SHA-256 digest of {@code normalizedLastName + '|' +
709	     * postcode}, so it is deterministic across calls and identical for every owner sharing the same
710	     * normalized last name and postcode — they belong to the same household automatically.
711	     *
712	     * @param lastName the last name of the household
713	     * @param postcode the postcode of the household (may be {@code null})
714	     * @return the deterministic household identifier
715	     */
716	    private static String householdIdFor(String lastName, String postcode) {
717	        String key = normalizeIdentity(lastName) + "|" + (postcode == null ? "" : postcode);
718	        try {
719	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
720	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
721	            StringBuilder sb = new StringBuilder(digest.length * 2);
722	            for (byte b : digest) {
723	                sb.append(String.format("%02x", b));
724	            }
725	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
726	        }
727	        catch (java.security.NoSuchAlgorithmException e) {
728	            throw new IllegalStateException("SHA-256 not available", e);
729	        }
730	    }
731	
732	    /**
733	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
734	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
735	     * single space, and the result is lower-cased.
736	     *
737	     * @param value the raw field value
738	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
739	     */
740	    private static String normalizeIdentity(String value) {
741	        if (value == null) {
742	            return "";
743	        }
744	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
745	    }
746	}
